"""Synthetic clips generated by derivgen and tiny native C1 models."""
import copy
import importlib.util
import json
from pathlib import Path
from types import SimpleNamespace
import numpy as np
import torch

K = Path(__file__).resolve().parents[1]


def camera_fixtures():
    from generator.derivgen_v7.derivgen.camera_rows import camera_rows, _encode
    c = np.tile(np.eye(4), (32,1,1))
    for k in range(32):
        a = k * .035
        c[k,:3,:3] = [[np.cos(a),0,np.sin(a)],[0,1,0],[-np.sin(a),0,np.cos(a)]]
        c[k,:3,3] = [k*.19, k*.003, k*.075]
    clip = dict(recording_id='h1-synthetic', dataset='scannet', scene='h1synthetic',
                frames=[dict(path=str(K/'tmp/b4'/f'frame{i}.png'),sha256='a'*64,source_index=i) for i in range(32)],
                fps=30., total_num_frames=32,
                **_encode(c, [[500,0,320],[0,500,240],[0,0,1]], [480,640], [0,-1,0]))
    from unittest.mock import patch
    # Synthetic scene only: no production exclusion file is available on this node.
    with patch('generator.derivgen_v7.derivgen.goal_exclusions.goal_tokens', return_value=set()):
        rows, refusals = camera_rows(clip, seed=17, per_type=4, distribution={}, manifest_dir=K/'tmp/b4'/'manifests')
    assert len(rows)==12, refusals
    return rows, clip, refusals


class CharacterTokenizer:
    pad_token_id = 0
    eos_token = '~'
    eos_token_id = ord('~')+128
    def encode(self, text, **kw):
        return [ord(c)+128 for c in text]
    def __call__(self, text, **kw):
        return dict(input_ids=self.encode(text), offset_mapping=[(i,i+1) for i in range(len(text))])
    def decode(self, ids, **kw):
        return ''.join(chr(i-128) for i in ids if i>=128)


class Processor:
    tokenizer = CharacterTokenizer()
    def apply_chat_template(self, messages, tokenize=False, add_generation_prompt=False):
        prefix = 'question<think>\n'
        return prefix if add_generation_prompt else prefix[:-len('<think>\n')]+messages[-1]['content']+'~\n'


def tiny():
    spec = importlib.util.spec_from_file_location('native_fixture', K/'tree/tests/test_carrier_c1.py')
    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    model, batch, targets = mod.fixture(training_mode='final', trace_program_version='3.14')
    # Keep native vision/carrier ids and give character traces a disjoint tiny vocabulary.
    model.model.language_model.embed_tokens = torch.nn.Embedding(512,32)
    model.lm_head = torch.nn.Linear(32,512,bias=False)
    model.config.text_config.vocab_size = 512
    model.depth_fov_source = 'pose_head'
    return model, batch, targets


def packed(raw, clip):
    from student_pilot.carrier_c1_routing import c1_row
    return c1_row(raw, clip)


def routing_batch(base, row):
    from student_pilot import carrier_c1_routing as r
    target, spans, segments = r.render_full(row['routing']['events'],row['routing']['answer'])
    ids, train, offsets = r.suffix_tokens(Processor(),row,target,spans)
    batch = copy.deepcopy(base)
    batch['aux_suffix_start'] = torch.tensor([int(torch.where(batch['labels'][0]!=-100)[0][0])])
    batch = r.splice(batch,ids,0)
    return r.finish(batch,ids,train,row,target,spans,'gt',offsets,segments)


def write_fixtures():
    rows,clip,refusals=camera_fixtures()
    (K/'rows/camera_fixtures.jsonl').write_text(''.join(json.dumps(r)+'\n' for r in rows))
    (K/'rows/camera_generation.json').write_text(json.dumps(dict(rows=len(rows),refusals=refusals),indent=2)+'\n')
    return rows,clip
